'use strict';
const fs=require('fs'),crypto=require('crypto'),{chromium}=require('playwright');
(async()=>{const html=fs.readFileSync('index.html'),browser=await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox']});const p=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:3,reducedMotion:'reduce'});await p.route('http://localhost:8765/**',r=>r.fulfill({body:html,contentType:'text/html'}));await p.goto('http://localhost:8765');const report=[],checks=[];
for(const sign of [-1,1]){await p.evaluate(sign=>{openMachine(machines[1]);machineProfile={squareness:{XY:{microns:sign*120},XZ:{microns:sign*120},YZ:{microns:sign*120}},guides:{},initialHeights:supports.map(()=>0)};supportHeights=supports.map(()=>0);updateLeveling(false);},sign);await p.evaluate(()=>document.fonts.ready);
for(const width of [320,390,1280]){await p.setViewportSize({width,height:width===1280?1000:844});await p.locator('#precisionReadouts').screenshot({path:`docs/qa-horizontal-motion-20261008/after/diagrams-${width}-sign${sign}-3x.png`});const text=await p.locator('#liveSquareness svg').evaluateAll(es=>es.map(e=>{const rect=b=>({x:b.x,y:b.y,w:b.width,h:b.height});return{viewbox:e.getAttribute('viewBox'),texts:[...e.querySelectorAll('text')].map(t=>({text:t.textContent,...rect(t.getBBox())})),relative:rect([...e.querySelectorAll('text')].find(t=>t.textContent==='相対').getBoundingClientRect()),body:rect(e.querySelector('.scan-body').getBoundingClientRect())};}));report.push({width,sign,text});for(let i=0;i<text.length;i++){const q=text[i];checks.push({name:`${width}/${sign}/${i} all text inside viewbox`,ok:q.texts.every(t=>t.x>=0&&t.x+t.w<=64&&t.y>=0&&t.y+t.h<=45)});checks.push({name:`${width}/${sign}/${i} relative label clears indicator body`,ok:q.relative.x>=q.body.x+q.body.w,detail:{relative:q.relative,body:q.body}});}}}
fs.writeFileSync('docs/qa-horizontal-motion-20261008/after/diagram-font-bounds.json',JSON.stringify({sha256:crypto.createHash('sha256').update(html).digest('hex'),checks,report},null,2));console.log(JSON.stringify({checks:checks.length,failed:checks.filter(q=>!q.ok)}));await browser.close();process.exitCode=checks.some(q=>!q.ok)?1:0;})().catch(e=>{console.error(e);process.exitCode=1;});
